var f=new Intl.NumberFormat("en-US");
function bench(){let n=0;for(let i=0;i<100;i++){if(f.format(1234.5)!=="1,234.5")throw Error("format");n++;}return n;}
bench();

var f=new Intl.NumberFormat("en-US");
function bench(){let n=0;for(let i=0;i<100;i++){const p=f.formatToParts(1234.5);if(p.map(x=>x.type).join()!=="integer,group,integer,decimal,fraction"||p.map(x=>x.value).join("")!=="1,234.5")throw Error("parts");n++;}return n;}
bench();

var f=new Intl.DateTimeFormat("en-US",{timeZone:"UTC",year:"numeric",month:"2-digit",day:"2-digit"});
function bench(){let n=0;for(let i=0;i<100;i++){const p=f.formatToParts(1704067200000);const o={};for(const x of p)o[x.type]=x.value;if(o.year!=="2024"||o.month!=="01"||o.day!=="01")throw Error("date");n++;}return n;}
bench();

var f=new Intl.Collator("en-US");
function bench(){let n=0;for(let i=0;i<1000;i++){if(!(f.compare("a","b")<0))throw Error("compare");n++;}return n;}
bench();

var f=new Intl.PluralRules("en-US");
function bench(){let n=0;for(let i=0;i<100;i++){if(f.select(1)!=="one"||f.select(2)!=="other")throw Error("plural");n++;}return n;}
bench();

var f=new Intl.Segmenter("en-US",{granularity:"word"});
function bench(){let n=0;for(let i=0;i<100;i++){let words=0;for(const x of f.segment("one two"))if(x.isWordLike)words++;if(words!==2)throw Error("segments");n+=words;}return n;}
bench();

var f=new Intl.ListFormat("en-US",{style:"long",type:"conjunction"});
function bench(){let n=0;for(let i=0;i<100;i++){if(f.format(["A","B","C"])!=="A, B, and C")throw Error("list");n++;}return n;}
bench();

var f=new Intl.RelativeTimeFormat("en-US",{numeric:"always"});
function bench(){let n=0;for(let i=0;i<100;i++){if(f.format(-1,"day")!=="1 day ago")throw Error("relative");n++;}return n;}
bench();

var f=new Intl.DisplayNames("en-US",{type:"region"});
function bench(){let n=0;for(let i=0;i<100;i++){const name=f.of("US");if(name!=="United States")throw Error("DisplayNames.of(US) returned "+name);n++;}return n;}
bench();

var f=new Intl.DurationFormat("en-US",{style:"long"});
function bench(){let n=0;for(let i=0;i<100;i++){const p=f.formatToParts({hours:1,minutes:2});if(p.filter(x=>x.type==="integer").map(x=>x.value).join()!=="1,2")throw Error("duration");n++;}return n;}
bench();

var start=Temporal.PlainDate.from("2024-01-01");
function bench(){let d=start;for(let i=0;i<100;i++)d=d.add({days:1});return d.since(start).days;}
bench();

var a=Temporal.PlainDate.from("2024-01-01"),b=Temporal.PlainDate.from("2024-02-01");
function bench(){let n=0;for(let i=0;i<100;i++)n+=a.until(b).days;return n;}
bench();

var start=Temporal.PlainDateTime.from("2024-01-01T00:00");
function bench(){let d=start;for(let i=0;i<100;i++)d=d.add({minutes:1});return d.hour*60+d.minute;}
bench();

var a=Temporal.Instant.from("2024-01-01T00:00:00.123456789Z");
function bench(){let n=0;for(let i=0;i<100;i++){if(a.round({smallestUnit:"millisecond",roundingMode:"halfExpand"}).epochMilliseconds!==1704067200123)throw Error("round");n++;}return n;}
bench();

var d=Temporal.Duration.from("PT90M");
function bench(){let n=0;for(let i=0;i<100;i++){const r=d.round({largestUnit:"hour",smallestUnit:"minute"});if(r.hours!==1||r.minutes!==30)throw Error("duration");n++;}return n;}
bench();
